 public record PolicyResponse(String id,String policyId,String code,String title,String description,String legalBasis,String policyReference,String privacyNotice,String eligibilityGuidance,String evidenceRequirements,int reviewIntervalMonths,int membershipValidityMonths,int minimumAggregateCohort,boolean requiresEmployeeNotice,boolean requiresEmployeeConsent,boolean allowsSelfExpression,boolean requiresCommitteeReview,boolean requiresAgencyHeadDecision,int definitionVersion,String supersedesId,String status,LocalDate effectiveFrom,LocalDate effectiveTo,long recordVersion){}
